using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncDisposable
{
    private readonly FakeProvider provider = new();

    [Fact]
    public async Task Sends_a_POST_with_the_reference_amount_and_currency_as_json()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.ContentType);
        using var json = JsonDocument.Parse(provider.Body);
        var root = json.RootElement;
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved","id":"auth_1","extra":{"a":1}}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-1", new Money(5, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-2", new Money(5, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-3", new Money(5, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-4", new Money(5, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        provider.Respond(status, """{"error":"nope"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            Gateway().AuthorizeAsync("ORD-5", new Money(5, "USD"), CancellationToken.None));
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_an_error()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(() =>
            Gateway().AuthorizeAsync("ORD-6", new Money(5, "USD"), CancellationToken.None));
    }

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    public async ValueTask DisposeAsync() => await provider.DisposeAsync();

    private sealed class FakeProvider : IAsyncDisposable
    {
        private readonly HttpListener listener = new();
        private readonly Task loop;
        private int status = 200;
        private string responseBody = "";

        public FakeProvider()
        {
            // Retry on a different port if another process grabbed the one we probed.
            for (var attempt = 0; ; attempt++)
            {
                var port = FreePort();
                listener.Prefixes.Clear();
                listener.Prefixes.Add($"http://127.0.0.1:{port}/");
                try { listener.Start(); BaseAddress = new Uri($"http://127.0.0.1:{port}"); break; }
                catch (HttpListenerException) when (attempt < 5) { }
            }
            loop = Task.Run(Serve);
        }

        public Uri BaseAddress { get; private set; } = null!;
        public string Method { get; private set; } = "";
        public string Path { get; private set; } = "";
        public string ContentType { get; private set; } = "";
        public string Body { get; private set; } = "";

        public void Respond(int statusCode, string body) { status = statusCode; responseBody = body; }

        private async Task Serve()
        {
            try
            {
                var context = await listener.GetContextAsync();
                var request = context.Request;
                Method = request.HttpMethod;
                Path = request.Url!.AbsolutePath;
                ContentType = request.ContentType ?? "";
                using (var reader = new StreamReader(request.InputStream, Encoding.UTF8)) Body = await reader.ReadToEndAsync();

                var bytes = Encoding.UTF8.GetBytes(responseBody);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
            catch (Exception ex) when (ex is HttpListenerException or ObjectDisposedException) { }
        }

        private static int FreePort()
        {
            var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();
            return port;
        }

        public async ValueTask DisposeAsync()
        {
            listener.Close();
            await loop;
        }
    }
}
